import json,os
# Usage: python3 list_invictus_tree_roots.py <Invictus mod folder> <this repo>; then run this script.
HERE=os.path.dirname(os.path.abspath(__file__)); REPO=os.path.dirname(os.path.dirname(HERE))
t=json.load(open(os.path.join(HERE,'trees.json')))
skip={'mlhu_unify_homeland','gm_subject_independence','tribal_reform'}
roots=[]
for k,v in sorted(t.items()):
    if v['generic'] or k in skip: continue
    for r in v['roots']:
        if r not in roots: roots.append(r)
lines=['﻿# Unify Your Home Lands (MLHU) - one tree or the other.',
'# Generated by tools/mission_audit/gen_invictus_tree_trigger.py from the Invictus 2.0.5 mission files',
'# (plus this mod\'s overrides). Lists the first tasks (tasks without "requires") of every Invictus',
'# mission tree except the generic ones (conquer region, home infrastructure, subject independence,',
'# tribal reform). Any other task of a tree needs one of these first, so checking them is enough.',
'# Country scope. True once the nation has finished (or bypassed) the first task of an Invictus tree.',
'mlhu_invictus_tree_started_trigger = {',
'\tOR = {']
lines+=['\t\thas_completed_mission_task = %s'%r for r in roots]
lines+=['\t}','}','']
p=os.path.join(REPO,'common/scripted_triggers/zz_mlhu_invictus_tree_triggers.txt')
open(p,'w',encoding='utf-8',newline='\n').write('\n'.join(lines))
print(len(roots))
